using Wolverine.Http;
using Wolverine.Marten;
using Campaigns.Contracts;

namespace Campaigns.Slices.Campaigns;

/// <summary>
/// A CREATE slice: the id is minted here, so the stream cannot exist and there is nothing to fetch.
/// <c>MartenOps.StartStream</c> rather than the aggregate handler workflow — the full reasoning is in
/// reference-implementations/state-change/, and this folder does not repeat it.
///
/// The write side of this model exists only to produce events for the five views to be built from. It
/// is deliberately the thinnest legal implementation of each slice.
/// </summary>
public static class OpenCampaignEndpoint
{
    public const string Route = "/campaigns";

    [WolverinePost(Route), EmptyResponse]
    public static (CampaignOpened, IStartStream) Open(OpenCampaign command)
    {
        // terminal="campaignId:generated" and terminal="openedAt:clock". Honouring a supplied id is what
        // lets a test name the stream it is about to assert on.
        var campaignId = command.CampaignId == Guid.Empty ? Guid.NewGuid() : command.CampaignId;

        var opened = new CampaignOpened(campaignId, command.Name, DateTimeOffset.UtcNow);

        return (opened, MartenOps.StartStream<CloseCampaignState>(campaignId, opened));
    }
}
